@Composable
fun HomeScreen(vm:MainViewModel,fixed:List<FixedExpenseEntity>,installments:List<InstallmentEntity>,assets:List<AssetEntity>,transactions:List<TransactionEntity>,months:List<MonthlyPlanEntity>,contract:FuzulContractEntity?,onImportExcel:()->Unit,onOpenPlan:()->Unit,onOpenFuzul:()->Unit){
    val now=YearMonth.now().toString();val current=months.firstOrNull{it.month==now}?:months.firstOrNull();val income=current?.let{it.meteIncome+it.esmaIncome+it.otherIncome}?:0.0;val expense=current?.let{vm.repo.planExpense(it,fixed,installments)}?:0.0;val net=current?.let{vm.repo.planNet(it,fixed,installments)}?:0.0;val fuzul=current?.fuzulPayment?:0.0;val totalAssets=assets.sumOf{vm.repo.currentAssetValue(it)};val monthTx=transactions.filter{it.date.startsWith(now)&&it.includedInBudget};val upcoming=nextFuzul(months)
    LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
        item{SectionTitle("Merhaba 👋","Tüm finansını tek ekranda takip et")}
        if(months.isEmpty()&&fixed.isEmpty()&&contract==null)item{EmptyState("Excel planını aktar","Mevcut bütçe dosyanı seçtiğinde sabit giderler, taksitler, aylık plan, Fuzul sözleşmesi ve işlem geçmişi otomatik içe alınır.","Excel'i seç",onImportExcel)}
        item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("Planlanan gelir",tl0(income),Green,modifier=Modifier.weight(1f));MetricCard("Planlanan gider",tl0(expense),Red,modifier=Modifier.weight(1f))}}
        item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("Fuzul bu ay",tl0(fuzul),Blue,modifier=Modifier.weight(1f));MetricCard("Ay sonu",tl0(net),if(net>=0)Green else Red,modifier=Modifier.weight(1f))}}
        if(assets.isNotEmpty())item{MetricCard("Toplam varlık",tl(totalAssets),Teal,"Vadeli hesap + nakit + altın / diğer")}
        item{AppCard(onClick=onOpenFuzul){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Rounded.DirectionsCar,null,tint=Blue);Text("Yaklaşan Fuzul",fontWeight=FontWeight.Bold,fontSize=16.sp,modifier=Modifier.padding(start=8.dp).weight(1f));Icon(Icons.Rounded.ChevronRight,null,tint=Muted)};if(upcoming!=null){Text("05 ${monthLabel(upcoming.month)}",color=Muted,fontSize=13.sp,modifier=Modifier.padding(top=10.dp));Text(tl(upcoming.fuzulPayment+upcoming.orgFee),fontWeight=FontWeight.Bold,fontSize=24.sp,modifier=Modifier.padding(top=2.dp));runCatching{YearMonth.parse(upcoming.month).atDay(5)}.getOrNull()?.let{d->val days=ChronoUnit.DAYS.between(LocalDate.now(),d);Text(if(days>=0)"$days gün kaldı" else "${abs(days)} gün gecikmiş",color=if(days>=0)Teal else Red,fontWeight=FontWeight.SemiBold,modifier=Modifier.padding(top=4.dp))}}else Text("Aktif ödeme görünmüyor",color=Muted,modifier=Modifier.padding(top=10.dp))}}
        contract?.let{ct->item{AppCard(onClick=onOpenFuzul){Text("TAHSİSAT",color=Blue,fontSize=11.sp,fontWeight=FontWeight.Bold);Text(dateLabel(ct.allocationDate),fontSize=20.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=4.dp));val idx=months.indexOfFirst{it.month==ct.allocationDate.take(7)};val paid=ct.downPayment+if(idx>=0)months.take(idx+1).sumOf{it.fuzulPayment}else 0.0;KeyValue("Peşinat + taksit",tl(paid),modifier=Modifier.padding(top=10.dp));KeyValue("Sözleşme oranı",pct(if(ct.amount>0)paid/ct.amount else 0.0),modifier=Modifier.padding(top=5.dp))}}}
        item{AppCard(onClick=onOpenPlan){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Rounded.ShowChart,null,tint=Teal);Text("6 aylık nakit projeksiyonu",fontWeight=FontWeight.Bold,fontSize=16.sp,modifier=Modifier.padding(start=8.dp))};val vals=months.take(6).map{vm.repo.planNet(it,fixed,installments)};if(vals.size>1)MiniLineChart(vals,Modifier.padding(top=10.dp))else Text("Plan verisi yok",color=Muted,modifier=Modifier.padding(top=10.dp))}}
        if(monthTx.isNotEmpty())item{AppCard{Text("GERÇEKLEŞEN — ${monthLabel(now)}",color=Teal,fontSize=11.sp,fontWeight=FontWeight.Bold);KeyValue("İçe aktarılan gelir",tl(monthTx.filter{it.amount>0}.sumOf{it.amount}),Green,Modifier.padding(top=10.dp));KeyValue("İçe aktarılan gider",tl(-monthTx.filter{it.amount<0}.sumOf{it.amount}),Red,Modifier.padding(top=6.dp))}}
    }
}

@Composable
fun PlanScreen(vm:MainViewModel,months:List<MonthlyPlanEntity>,fixed:List<FixedExpenseEntity>,installments:List<InstallmentEntity>){var edit by remember{mutableStateOf<MonthlyPlanEntity?>(null)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{SectionTitle("Aylık Plan","Gelir, gider, kart ve Fuzul projeksiyonu")};if(months.isEmpty())item{EmptyState("Plan bulunamadı","Dosya Merkezi'nden bütçe Excel'ini içe aktarabilirsin.")};items(months,key={it.month}){m->val expense=vm.repo.planExpense(m,fixed,installments);val net=vm.repo.planNet(m,fixed,installments);AppCard(onClick={edit=m}){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(monthLabel(m.month),fontSize=16.sp,fontWeight=FontWeight.Bold);Text("Gelir ${tl0(m.meteIncome+m.esmaIncome+m.otherIncome)} • Gider ${tl0(expense)} • Fuzul ${tl0(m.fuzulPayment)}",fontSize=12.sp,color=Muted,modifier=Modifier.padding(top=5.dp))};Pill(if(net>=0)"+${tl0(net)}" else tl0(net),if(net>=0)Green else Red)}}}};edit?.let{EditMonthDialog(it,vm){edit=null}}}

@Composable
private fun EditMonthDialog(item:MonthlyPlanEntity,vm:MainViewModel,onDismiss:()->Unit){var mete by remember{mutableStateOf(item.meteIncome.toString())};var esma by remember{mutableStateOf(item.esmaIncome.toString())};var otherIncome by remember{mutableStateOf(item.otherIncome.toString())};var org by remember{mutableStateOf(item.orgFee.toString())};var bills by remember{mutableStateOf(item.billsSnapshot.toString())};var living by remember{mutableStateOf(item.living.toString())};var cards by remember{mutableStateOf(item.cardsSnapshot.toString())};var edu by remember{mutableStateOf(item.educationSnapshot.toString())};var transport by remember{mutableStateOf(item.transport.toString())};var other by remember{mutableStateOf(item.otherSnapshot.toString())};var fuzul by remember{mutableStateOf(item.fuzulPayment.toString())};AlertDialog(onDismissRequest=onDismiss,title={Text(monthLabel(item.month))},text={LazyColumn(Modifier.heightIn(max=520.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{FormField("Mete gelir",mete,{mete=it},true)};item{FormField("Esma gelir",esma,{esma=it},true)};item{FormField("Diğer gelir",otherIncome,{otherIncome=it},true)};item{FormField("Org. ücreti",org,{org=it},true)};item{FormField("Faturalar + iletişim",bills,{bills=it},true)};item{FormField("Market + giyim + yeme",living,{living=it},true)};item{FormField("Kart snapshot",cards,{cards=it},true)};item{FormField("Çocuk / eğitim",edu,{edu=it},true)};item{FormField("Ulaşım / yakıt",transport,{transport=it},true)};item{FormField("Diğer / kişisel",other,{other=it},true)};item{FormField("Fuzul taksiti",fuzul,{fuzul=it},true)}}},confirmButton={TextButton(onClick={vm.saveMonth(item.copy(meteIncome=doubleInput(mete),esmaIncome=doubleInput(esma),otherIncome=doubleInput(otherIncome),orgFee=doubleInput(org),billsSnapshot=doubleInput(bills),living=doubleInput(living),cardsSnapshot=doubleInput(cards),educationSnapshot=doubleInput(edu),transport=doubleInput(transport),otherSnapshot=doubleInput(other),fuzulPayment=doubleInput(fuzul)));onDismiss()}){Text("Kaydet")}},dismissButton={TextButton(onClick=onDismiss){Text("Vazgeç")}})}

@Composable
fun TransactionsScreen(transactions:List<TransactionEntity>){var q by remember{mutableStateOf("")};val filtered=if(q.isBlank())transactions else transactions.filter{it.description.contains(q,true)||it.category.contains(q,true)||it.source.contains(q,true)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{SectionTitle("İşlemler","Ekstre ve hesap hareketlerinden gelen gerçek kayıtlar");Spacer(Modifier.height(12.dp));OutlinedTextField(q,{q=it},label={Text("Ara")},leadingIcon={Icon(Icons.Rounded.Search,null)},singleLine=true,modifier=Modifier.fillMaxWidth())};if(filtered.isEmpty())item{EmptyState("İşlem yok","Dosya Merkezi'nden kredi kartı ekstresi veya hesap hareketi yükleyebilirsin.")};items(filtered.take(500),key={it.id}){t->AppCard{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(t.description,fontWeight=FontWeight.SemiBold,maxLines=2,overflow=TextOverflow.Ellipsis);Text("${dateLabel(t.date)} • ${t.source}",fontSize=12.sp,color=Muted,modifier=Modifier.padding(top=3.dp));Text(t.category,fontSize=11.sp,color=Blue,modifier=Modifier.padding(top=4.dp))};Text(tl(t.amount),color=if(t.amount>=0)Green else Red,fontWeight=FontWeight.Bold)}}}}}

@Composable
fun FuzulScreen(vm:MainViewModel,contract:FuzulContractEntity?,months:List<MonthlyPlanEntity>,fixed:List<FixedExpenseEntity>,installments:List<InstallmentEntity>){var vehicle by remember{mutableStateOf("2800000")};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{SectionTitle("Fuzul","Sözleşme, taksit planı ve araç farkı")};if(contract==null){item{EmptyState("Sözleşme bulunamadı","Bütçe Excel'i içe aktarıldığında FUZUL_SOZLESME sayfası otomatik okunur.")};return@LazyColumn};item{AppCard{KeyValue("Finansman türü",contract.fundingType);KeyValue("Sözleşme tutarı",tl(contract.amount),modifier=Modifier.padding(top=6.dp));KeyValue("Peşinat",tl(contract.downPayment),modifier=Modifier.padding(top=6.dp));KeyValue("Organizasyon ücreti",tl(contract.organizationFee),modifier=Modifier.padding(top=6.dp));KeyValue("Tahsisat",dateLabel(contract.allocationDate),modifier=Modifier.padding(top=6.dp));KeyValue("Son taksit",dateLabel(contract.lastPaymentDate),modifier=Modifier.padding(top=6.dp))}};if(contract.fundingType.contains("Konut",true))item{AppCard{Text("Sözleşmede finansman türü “Konut” görünüyor",color=Red,fontWeight=FontWeight.Bold);Text("Araç kullanımı için yazılı teyit almak iyi olur.",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=5.dp))}};item{val idx=months.indexOfFirst{it.month==contract.allocationDate.take(7)};val paid=contract.downPayment+if(idx>=0)months.take(idx+1).sumOf{it.fuzulPayment}else 0.0;AppCard{Text("ÖDEME İLERLEMESİ",color=Blue,fontSize=11.sp,fontWeight=FontWeight.Bold);Text(pct(if(contract.amount>0)paid/contract.amount else 0.0),fontSize=26.sp,fontWeight=FontWeight.Bold,color=Green,modifier=Modifier.padding(top=4.dp));LinearProgressIndicator(progress={if(contract.amount>0)(paid/contract.amount).toFloat().coerceIn(0f,1f)else 0f},modifier=Modifier.fillMaxWidth().padding(top=8.dp));KeyValue("Peşinat + taksit",tl(paid),modifier=Modifier.padding(top=8.dp))}};item{Text("Taksit planı",fontSize=18.sp,fontWeight=FontWeight.Bold)};items(months.filter{it.fuzulPayment>0},key={it.month}){m->AppCard{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("05 ${monthLabel(m.month)}",fontWeight=FontWeight.Bold);Text("Taksit ${tl(m.fuzulPayment)}${if(m.orgFee>0)" + Org. ${tl(m.orgFee)}" else ""}",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=4.dp))};Checkbox(m.fuzulPaid,{vm.saveMonth(m.copy(fuzulPaid=it))})}}};item{AppCard{Text("ARAÇ FİYATI / NAKİT FARK",color=Teal,fontSize=11.sp,fontWeight=FontWeight.Bold);FormField("Tahsisatta araç fiyatı",vehicle,{vehicle=it},true);val price=doubleInput(vehicle);val diff=max(price-contract.amount,0.0);var cash=contract.openingCash;months.filter{it.month<=contract.allocationDate.take(7)}.forEach{cash+=vm.repo.planNet(it,fixed,installments)};val shortage=max(diff-cash,0.0);KeyValue("Fuzul tahsisat",tl(contract.amount),modifier=Modifier.padding(top=10.dp));KeyValue("Sizin tamamlayacağınız",tl(diff),if(diff>0)Red else Green,Modifier.padding(top=6.dp));KeyValue("Tahmini serbest nakit",tl(cash),modifier=Modifier.padding(top=6.dp));KeyValue(if(shortage>0)"Ek nakit ihtiyacı" else "Fark sonrası kalan",tl(if(shortage>0)shortage else cash-diff),if(shortage>0)Red else Green,Modifier.padding(top=6.dp))}}}}

@Composable
fun MoreScreen(onFixed:()->Unit,onCards:()->Unit,onAssets:()->Unit,onFiles:()->Unit,onReports:()->Unit){val menu=listOf(Triple("Sabit Giderler","Faturalar, abonelikler, servis, harçlık",Icons.Rounded.Payments)to onFixed,Triple("Kartlar & Taksitler","Ekstre, kalan taksit, gelecek aylık yük",Icons.Rounded.CreditCard)to onCards,Triple("Varlıklar","Vadeli hesap, nakit, altın ve diğer birikimler",Icons.Rounded.AccountBalance)to onAssets,Triple("Dosya Merkezi","Excel, PDF, CSV, yedek ve içe aktarma",Icons.Rounded.UploadFile)to onFiles,Triple("Raporlar","Gelir-gider, kategori ve nakit projeksiyonu",Icons.Rounded.BarChart)to onReports);LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{SectionTitle("Daha Fazla","Finans yönetim araçları")};items(menu){(t,action)->AppCard(onClick=action){Row(verticalAlignment=Alignment.CenterVertically){Icon(t.third,null,tint=Blue,modifier=Modifier.size(28.dp));Column(Modifier.weight(1f).padding(start=12.dp)){Text(t.first,fontWeight=FontWeight.Bold,fontSize=16.sp);Text(t.second,color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=3.dp))};Icon(Icons.Rounded.ChevronRight,null,tint=Muted)}}}}}

private fun nextFuzul(months:List<MonthlyPlanEntity>):MonthlyPlanEntity?{val now=YearMonth.now();return months.filter{it.fuzulPayment>0&&!it.fuzulPaid}.sortedBy{it.month}.firstOrNull{runCatching{!YearMonth.parse(it.month).isBefore(now)}.getOrDefault(false)}?:months.filter{it.fuzulPayment>0&&!it.fuzulPaid}.sortedBy{it.month}.firstOrNull()}
